namespace sv_c063ab0850314c4896a67089b94c53e6.Services;

public class WarehouseState
{
    public string SelectedWarehouseId { get; private set; } = "warehouse-a";
    public string SelectedWarehouseName { get; private set; } = "Warehouse A";

    public event Action? OnChange;

    public static readonly Dictionary<string, string> AvailableWarehouses = new()
    {
        ["warehouse-a"] = "Warehouse A",
        ["warehouse-b"] = "Warehouse B",
        ["warehouse-c"] = "Warehouse C",
        ["warehouse-d"] = "Warehouse D"
    };

    public void SetWarehouse(string warehouseId)
    {
        if (AvailableWarehouses.TryGetValue(warehouseId, out var name))
        {
            SelectedWarehouseId = warehouseId;
            SelectedWarehouseName = name;
            OnChange?.Invoke();
        }
    }
}

namespace sv_c063ab0850314c4896a67089b94c53e6.Services;

/// <summary>
/// Scoped service that manages low-stock alert polling for the current user's circuit.
/// Components subscribe to OnAlertCountChanged to receive updates.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private Timer? _pollingTimer;
    private int _subscriberCount;
    private readonly Random _random = new();

    public int CurrentLowStockCount { get; private set; }

    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count for a warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Start polling. Uses reference counting so multiple components can request polling
    /// but only one timer runs.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_pollingTimer is null)
        {
            _pollingTimer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
        }
    }

    /// <summary>
    /// Stop polling when a component disposes. Timer stops when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _pollingTimer?.Dispose();
            _pollingTimer = null;
        }
    }

    private async void PollCallback(object? state)
    {
        var count = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        CurrentLowStockCount = count;
        OnAlertCountChanged?.Invoke();
    }

    private async void OnWarehouseChanged()
    {
        // When warehouse changes, immediately refresh the alert count
        if (_pollingTimer is not null)
        {
            var count = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
            CurrentLowStockCount = count;
            OnAlertCountChanged?.Invoke();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        _pollingTimer?.Dispose();
        _pollingTimer = null;
    }
}

