@using sv_c063ab0850314c4896a67089b94c53e6.Services
@inject WarehouseState WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<select class="form-select form-select-sm" value="@WarehouseState.SelectedWarehouseId"
        @onchange="OnWarehouseSelected" style="max-width: 200px;">
    @foreach (var wh in WarehouseState.AvailableWarehouses)
    {
        <option value="@wh.Key">@wh.Value</option>
    }
</select>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnStateChanged;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.SetWarehouse(id);
        }
    }

    private void OnStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= OnStateChanged;
    }
}

@using sv_c063ab0850314c4896a67089b94c53e6.Services
@inject InventoryAlertService AlertService
